package mail

import (
	"bytes"
	"encoding/base64"
	"errors"
	"fmt"
	"math/rand/v2"
	"regexp"
	"strings"
)

// The code below ports the parts of Python's email.message.MIMEPart,
// email.contentmanager and email.generator.BytesGenerator that Django's
// EmailMessage.message() and as_bytes() use.

// policy holds the settings of a Python email policy that change the
// generated bytes. Both policies fold lines at 78 characters.
type policy struct {
	// linesep ends every generated line.
	linesep string
}

// The policies of Django's messages: policy.default for message() and the
// console, file and locmem backends, policy.SMTP for the SMTP backend.
var (
	policyDefault = policy{linesep: "\n"}
	policySMTP    = policy{linesep: "\r\n"}
)

// mimeHeader is one header of an entity.
type mimeHeader struct {
	name string
	// tree is the parse tree that folding reads.
	tree *tok
	// isMedia marks a Content-Type or Content-Disposition header, whose
	// value is media followed by params.
	isMedia bool
	media   string
	params  []param
	// isSource marks a header read from a parsed message; source holds its
	// value as Python's header_source_parse keeps it.
	isSource bool
	source   string
}

// mediaTree returns the parse tree of a Content-Type or Content-Disposition
// value, as parse_content_type_header and
// parse_content_disposition_header build it.
func mediaTree(name, media string, params []param) *tok {
	typ := "content-disposition"
	if strings.EqualFold(name, "content-type") {
		typ = "content-type"
	}
	t := &tok{typ: typ, noEW: true, noBreak: true}
	if typ == "content-type" {
		maintype, subtype, _ := strings.Cut(media, "/")
		t.add(newList("token", valueTerm(maintype, "ttext")), valueTerm("/", "content-type-separator"),
			newList("token", valueTerm(subtype, "ttext")))
	} else {
		t.add(newList("token", valueTerm(media, "ttext")))
	}
	if len(params) > 0 {
		t.add(valueTerm(";", "parameter-separator"),
			&tok{typ: "mime-parameters", noBreak: true, params: append([]param(nil), params...)})
	}
	return t
}

// fold returns the folded header line, as policy.fold_binary does.
func (h *mimeHeader) fold(p policy) (string, error) {
	var folded string
	switch {
	case h.isSource:
		folded = foldSource(h.name, h.source, p)
	case h.isMedia:
		folded = foldHeader(h.name, mediaTree(h.name, h.media, h.params), p.linesep)
	default:
		folded = foldHeader(h.name, h.tree, p.linesep)
	}
	if !h.isSource && !isASCII(folded) {
		return "", fmt.Errorf("'ascii' codec can't encode the header %s", pyRepr(folded))
	}
	body := strings.TrimSuffix(folded, p.linesep)
	if !strings.HasSuffix(folded, p.linesep) || newlineWithoutFWS.MatchString(body) {
		return "", fmt.Errorf("folded header contains newline: %s", pyRepr(folded))
	}
	return folded, nil
}

// newlineWithoutFWS finds a line break that does not start a continuation
// line, which Python's generator refuses to write.
var newlineWithoutFWS = regexp.MustCompile(`\r\n[^ \t]|\r[^ \n\t]|\n[^ \t]`)

// foldSource folds a header read from a parsed message, as policy._fold
// does for a string value: the source lines stay unless one is too long.
// A value with 8-bit bytes keeps its lines, where Python would encode it.
func foldSource(name, value string, p policy) string {
	lines := splitLinesep(value)
	refold := len(lines) > 0 && runeLen(lines[0])+runeLen(name)+2 > maxLineLength
	for _, line := range lines[min(1, len(lines)):] {
		if runeLen(line) > maxLineLength {
			refold = true
		}
	}
	if refold && isASCII(value) {
		tree, err := parseHeader(name, strings.Join(lines, ""))
		if err == nil {
			return foldHeader(name, tree, p.linesep)
		}
	}
	return name + ": " + strings.Join(lines, p.linesep) + p.linesep
}

// splitLinesep splits s at "\n", "\r\n" and "\r", as the linesep_splitter
// of Python's email.policy does. Unlike str.splitlines(), it keeps the
// other line breaks of Unicode and gives an empty last line after a final
// break.
func splitLinesep(s string) []string {
	var lines []string
	start := 0
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\n':
			lines = append(lines, s[start:i])
			start = i + 1
		case '\r':
			lines = append(lines, s[start:i])
			if i+1 < len(s) && s[i+1] == '\n' {
				i++
			}
			start = i + 1
		}
	}
	return append(lines, s[start:])
}

// entity is a MIME entity under construction, as Python's MIMEPart holds
// it: ordered headers and a payload.
type entity struct {
	headers []*mimeHeader
	// text is the encoded payload of a leaf entity. hasText is false for
	// Python's None payload.
	text    string
	hasText bool
	// parts holds the subparts of a multipart entity, or the one message of
	// a message entity.
	parts []*entity
	// emailMessage marks Python's EmailMessage class, whose set_content
	// adds MIME-Version.
	emailMessage bool
	// raw marks a message read from bytes, whose body text is written as
	// it is, apart from the line breaks.
	raw bool
}

// get returns the first header called name, or nil.
func (e *entity) get(name string) *mimeHeader {
	for _, h := range e.headers {
		if strings.EqualFold(h.name, name) {
			return h
		}
	}
	return nil
}

// countCheck fails when the entity already holds the most headers called
// name that it may hold, as Message.__setitem__ does.
func (e *entity) countCheck(name string) error {
	if !uniqueHeader(name) {
		return nil
	}
	if e.get(name) != nil {
		return fmt.Errorf("There may be at most 1 %s headers in a message", name) //nolint:revive,staticcheck // Python's message
	}
	return nil
}

// set appends the header name: value, as msg[name] = value does.
func (e *entity) set(name, value string) error {
	if err := e.countCheck(name); err != nil {
		return err
	}
	h, err := storeHeader(name, value)
	if err != nil {
		return err
	}
	e.headers = append(e.headers, h)
	return nil
}

// setMedia appends a Content-Type or Content-Disposition header.
func (e *entity) setMedia(name, media string, params ...param) error {
	if err := e.countCheck(name); err != nil {
		return err
	}
	e.headers = append(e.headers, &mimeHeader{name: name, isMedia: true, media: media, params: params})
	return nil
}

// storeHeader parses a header value, as policy.header_store_parse does.
func storeHeader(name, value string) (*mimeHeader, error) {
	if err := validateHeaderName(name); err != nil {
		return nil, err
	}
	if err := checkHeaderValue(value); err != nil {
		return nil, err
	}
	switch strings.ToLower(name) {
	case "content-type", "content-disposition":
		if media, params, ok := parseMediaValue(value); ok {
			return &mimeHeader{name: name, isMedia: true, media: media, params: params}, nil
		}
	}
	tree, err := parseHeader(name, value)
	if err != nil {
		return nil, err
	}
	return &mimeHeader{name: name, tree: tree}, nil
}

// parseMediaValue splits a Content-Type or Content-Disposition value into
// the media and its decoded parameters. It reports false for a value it
// cannot read, which is then kept as unstructured text.
func parseMediaValue(value string) (string, []param, bool) {
	media, rest, _ := strings.Cut(value, ";")
	media = strings.TrimSpace(media)
	if media == "" || strings.ContainsAny(media, " \t\"()<>@,:\\[]?=") {
		return "", nil, false
	}
	var params []param
	for rest != "" {
		var item string
		item, rest = cutParam(rest)
		item = strings.TrimSpace(item)
		if item == "" {
			continue
		}
		name, val, hasValue := strings.Cut(item, "=")
		name, val = strings.TrimSpace(name), strings.TrimSpace(val)
		if !hasValue {
			params = append(params, param{name: name})
			continue
		}
		if strings.HasPrefix(val, `"`) && strings.HasSuffix(val, `"`) && len(val) >= 2 {
			val = unquoteParam(val[1 : len(val)-1])
		}
		if base, ok := strings.CutSuffix(name, "*"); ok {
			charset, encoded, found := strings.Cut(val, "'")
			if _, after, found2 := strings.Cut(encoded, "'"); found && found2 {
				if decoded, err := decodeCharset(percentDecode(after), charset); err == nil {
					name, val = base, decoded
				}
			}
		}
		params = append(params, param{name: name, value: val})
	}
	return media, params, true
}

// cutParam returns the text before the first ';' outside quotes and the
// text after it.
func cutParam(s string) (string, string) {
	quoted := false
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\\':
			i++
		case '"':
			quoted = !quoted
		case ';':
			if !quoted {
				return s[:i], s[i+1:]
			}
		}
	}
	return s, ""
}

// unquoteParam removes the backslash escapes of a quoted parameter value.
func unquoteParam(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// percentDecode decodes the %XX escapes of an RFC 2231 value.
func percentDecode(s string) []byte {
	out := make([]byte, 0, len(s))
	for i := 0; i < len(s); i++ {
		if s[i] == '%' && i+2 < len(s) && isHexDigit(s[i+1]) && isHexDigit(s[i+2]) {
			out = append(out, decodeQ(s[i:i+3])...)
			i += 2
			continue
		}
		out = append(out, s[i])
	}
	return out
}

// contentType returns the lowercased media type, text/plain when there is
// none or it is invalid, as get_content_type does.
func (e *entity) contentType() string {
	h := e.get("content-type")
	if h == nil {
		return "text/plain"
	}
	media := h.media
	if !h.isMedia {
		media, _, _ = strings.Cut(h.tree.String(), ";")
	}
	media = strings.ToLower(strings.TrimSpace(media))
	if strings.Count(media, "/") != 1 {
		return "text/plain"
	}
	return media
}

// maintype returns the main type of the content type.
func (e *entity) maintype() string {
	m, _, _ := strings.Cut(e.contentType(), "/")
	return m
}

// subtype returns the subtype of the content type.
func (e *entity) subtype() string {
	_, s, _ := strings.Cut(e.contentType(), "/")
	return s
}

// setParam sets the parameter name of the media header called header,
// replacing a parameter of the same name, as set_param does.
func (e *entity) setParam(header, name, value string) error {
	h := e.get(header)
	if h == nil {
		return fmt.Errorf("KeyError: %s", pyRepr(strings.ToLower(header)))
	}
	if !h.isMedia {
		return fmt.Errorf("the %s header has no parameters", header)
	}
	params := make([]param, 0, len(h.params)+1)
	found := false
	for _, p := range h.params {
		if strings.EqualFold(p.name, name) {
			p = param{name: name, value: value}
			found = true
		}
		params = append(params, p)
	}
	if !found {
		params = append(params, param{name: name, value: value})
	}
	h.params = params
	return nil
}

// clearContent removes the Content-* headers and the payload.
func (e *entity) clearContent() {
	kept := e.headers[:0]
	for _, h := range e.headers {
		if !strings.HasPrefix(strings.ToLower(h.name), "content-") {
			kept = append(kept, h)
		}
	}
	e.headers = kept
	e.text, e.hasText, e.parts = "", false, nil
}

// contentOptions are the optional arguments of Python's set_content.
type contentOptions struct {
	disposition string
	filename    string
	hasFilename bool
	cid         string
}

// prepareSet sets the Content-Type of a new payload.
func (e *entity) prepareSet(maintype, subtype string) error {
	return e.setMedia("Content-Type", maintype+"/"+subtype)
}

// finalizeSet adds the disposition, filename and Content-ID, as
// _finalize_set does.
func (e *entity) finalizeSet(o contentOptions) error {
	disposition := o.disposition
	if disposition == "" && o.hasFilename {
		disposition = "attachment"
	}
	if disposition != "" {
		if err := e.set("Content-Disposition", disposition); err != nil {
			return err
		}
	}
	if o.hasFilename {
		if err := e.setParam("Content-Disposition", "filename", o.filename); err != nil {
			return err
		}
	}
	if o.cid != "" {
		return e.set("Content-ID", o.cid)
	}
	return nil
}

// startContent runs the checks and clearing of set_content.
func (e *entity) startContent() error {
	if e.maintype() == "multipart" {
		return errors.New("set_content not valid on multipart")
	}
	e.clearContent()
	return nil
}

// endContent adds MIME-Version to an EmailMessage, as its set_content does.
func (e *entity) endContent() error {
	if e.emailMessage && e.get("MIME-Version") == nil {
		return e.set("MIME-Version", "1.0")
	}
	return nil
}

// setTextContent sets a text payload, as set_text_content does.
func (e *entity) setTextContent(text, subtype, charset string, o contentOptions, p policy) error {
	if err := e.startContent(); err != nil {
		return err
	}
	if err := e.prepareSet("text", subtype); err != nil {
		return err
	}
	cte, payload, err := encodeText(text, charset, p)
	if err != nil {
		return err
	}
	e.text, e.hasText = payload, true
	if err := e.setParam("Content-Type", "charset", charsetParam(charset)); err != nil {
		return err
	}
	if err := e.set("Content-Transfer-Encoding", cte); err != nil {
		return err
	}
	if err := e.finalizeSet(o); err != nil {
		return err
	}
	return e.endContent()
}

// setBytesContent sets a binary payload in base64, as set_bytes_content
// does.
func (e *entity) setBytesContent(data []byte, maintype, subtype string, o contentOptions) error {
	if err := e.startContent(); err != nil {
		return err
	}
	if err := e.prepareSet(maintype, subtype); err != nil {
		return err
	}
	e.text, e.hasText = encodeBase64Lines(data), true
	if err := e.set("Content-Transfer-Encoding", "base64"); err != nil {
		return err
	}
	if err := e.finalizeSet(o); err != nil {
		return err
	}
	return e.endContent()
}

// setMessageContent sets a message payload, as set_message_content does.
func (e *entity) setMessageContent(msg *entity, subtype string, o contentOptions) error {
	if subtype == "partial" {
		return errors.New("message/partial is not supported for Message objects")
	}
	cte := "7bit"
	if subtype == "rfc822" {
		cte = "8bit"
	}
	if err := e.startContent(); err != nil {
		return err
	}
	if err := e.prepareSet("message", subtype); err != nil {
		return err
	}
	e.parts = []*entity{msg}
	if err := e.set("Content-Transfer-Encoding", cte); err != nil {
		return err
	}
	if err := e.finalizeSet(o); err != nil {
		return err
	}
	return e.endContent()
}

// makeMultipart turns the entity into a multipart/subtype entity whose
// first part holds the existing content, as _make_multipart does.
func (e *entity) makeMultipart(subtype string, disallowed ...string) error {
	if e.maintype() == "multipart" {
		existing := e.subtype()
		for _, d := range append(disallowed, subtype) {
			if existing == d {
				return fmt.Errorf("Cannot convert %s to %s", existing, subtype) //nolint:revive,staticcheck // Python's message
			}
		}
	}
	var keep, content []*mimeHeader
	for _, h := range e.headers {
		if strings.HasPrefix(strings.ToLower(h.name), "content-") {
			content = append(content, h)
		} else {
			keep = append(keep, h)
		}
	}
	if len(content) > 0 {
		sub := &entity{headers: content, text: e.text, hasText: e.hasText, parts: e.parts, emailMessage: e.emailMessage}
		e.parts = []*entity{sub}
	} else {
		e.parts = []*entity{}
	}
	e.text, e.hasText = "", false
	e.headers = keep
	return e.set("Content-Type", "multipart/"+subtype)
}

// makeMixed turns the entity into multipart/mixed.
func (e *entity) makeMixed() error { return e.makeMultipart("mixed") }

// makeAlternative turns the entity into multipart/alternative.
func (e *entity) makeAlternative() error { return e.makeMultipart("alternative", "mixed") }

// addPart adds part to a multipart/subtype entity, converting the entity
// first, and gives the part the disposition disp unless it has one, as
// _add_multipart does.
func (e *entity) addPart(subtype string, part *entity, disp string) error {
	if e.contentType() != "multipart/"+subtype {
		var err error
		if subtype == "mixed" {
			err = e.makeMixed()
		} else {
			err = e.makeAlternative()
		}
		if err != nil {
			return err
		}
	}
	if disp != "" && part.get("content-disposition") == nil {
		if err := part.set("Content-Disposition", disp); err != nil {
			return err
		}
	}
	e.parts = append(e.parts, part)
	return nil
}

// encodeText encodes text in charset and picks the transfer encoding, as
// Python's contentmanager._encode_text does.
func encodeText(text, charset string, p policy) (string, string, error) {
	data, err := encodeCharset(text, charset)
	if err != nil {
		return "", "", err
	}
	lines := bytesSplitLines(data)
	normal := func(lines [][]byte) []byte {
		return append(bytes.Join(lines, []byte("\n")), '\n')
	}
	embedded := func(lines [][]byte) []byte {
		return append(bytes.Join(lines, []byte(p.linesep)), p.linesep...)
	}
	longest := 0
	for _, l := range lines {
		longest = max(longest, len(l))
	}
	if longest <= maxLineLength {
		body := normal(lines)
		if isASCII(string(body)) {
			return "7bit", string(body), nil
		}
		return "8bit", string(body), nil
	}
	sniff := embedded(lines[:min(10, len(lines))])
	sniffQP := qpBodyEncode(sniff, maxLineLength)
	if len(sniffQP) > (len(sniff)+2)/3*4+1 {
		return "base64", encodeBase64Lines(embedded(lines)), nil
	}
	if len(lines) <= 10 {
		return "quoted-printable", sniffQP, nil
	}
	return "quoted-printable", qpBodyEncode(normal(lines), maxLineLength), nil
}

// bytesSplitLines splits data at "\n", "\r" and "\r\n", as Python's
// bytes.splitlines() does.
func bytesSplitLines(data []byte) [][]byte {
	var lines [][]byte
	for len(data) > 0 {
		i := bytes.IndexAny(data, "\r\n")
		if i < 0 {
			lines = append(lines, data)
			break
		}
		lines = append(lines, data[:i])
		if data[i] == '\r' && i+1 < len(data) && data[i+1] == '\n' {
			i++
		}
		data = data[i+1:]
	}
	return lines
}

// encodeBase64Lines encodes data in base64 lines of 76 characters, each
// ending in "\n", as _encode_base64 does for 78-character lines.
func encodeBase64Lines(data []byte) string {
	const chunk = maxLineLength / 4 * 3
	var b strings.Builder
	for i := 0; i < len(data); i += chunk {
		b.WriteString(base64.StdEncoding.EncodeToString(data[i:min(i+chunk, len(data))]))
		b.WriteByte('\n')
	}
	return b.String()
}

// qpBodyEncode encodes data in quoted-printable with soft line breaks at
// maxlen, as Python's quoprimime.body_encode does with eol "\n".
func qpBodyEncode(data []byte, maxlen int) string {
	if len(data) == 0 {
		return ""
	}
	const hexDigits = "0123456789ABCDEF"
	var enc strings.Builder
	for _, c := range data {
		if c == '\r' || c == '\n' || c == '\t' || (c >= ' ' && c <= '~' && c != '=') {
			enc.WriteByte(c)
			continue
		}
		enc.WriteByte('=')
		enc.WriteByte(hexDigits[c>>4])
		enc.WriteByte(hexDigits[c&15])
	}
	body := enc.String()
	quote := func(c byte) string { return "=" + string(hexDigits[c>>4]) + string(hexDigits[c&15]) }
	const softBreak = "=\n"
	maxlen1 := maxlen - 1
	var out []string
	for _, line := range qpLines(body) {
		start := 0
		laststart := len(line) - 1 - maxlen
		for start <= laststart {
			stop := start + maxlen1
			switch {
			case line[stop-2] == '=':
				out = append(out, line[start:stop-1])
				start = stop - 2
			case line[stop-1] == '=':
				out = append(out, line[start:stop])
				start = stop - 1
			default:
				out = append(out, line[start:stop]+"=")
				start = stop
			}
		}
		if n := len(line); n > 0 && (line[n-1] == ' ' || line[n-1] == '\t') {
			room := start - laststart
			var q string
			switch {
			case room >= 3:
				q = quote(line[n-1])
			case room == 2:
				q = line[n-1:] + softBreak
			default:
				q = softBreak + quote(line[n-1])
			}
			out = append(out, line[start:n-1]+q)
		} else {
			out = append(out, line[start:])
		}
	}
	if last := body[len(body)-1]; last == '\r' || last == '\n' {
		out = append(out, "")
	}
	return strings.Join(out, "\n")
}

// qpLines splits quoted-printable text at "\r", "\n" and "\r\n", the only
// line breaks left after encoding, as str.splitlines() does.
func qpLines(s string) []string {
	var lines []string
	for s != "" {
		i := strings.IndexAny(s, "\r\n")
		if i < 0 {
			lines = append(lines, s)
			break
		}
		lines = append(lines, s[:i])
		if s[i] == '\r' && i+1 < len(s) && s[i+1] == '\n' {
			i++
		}
		s = s[i+1:]
	}
	return lines
}

// boundaryToken returns the random number of a new multipart boundary, as
// random.randrange(sys.maxsize) does. Tests replace it.
var boundaryToken = func() uint64 { return rand.Uint64N(1<<63 - 1) }

// makeBoundary returns a boundary that no line of text equals, as
// Generator._make_boundary does.
func makeBoundary(text string) string {
	boundary := strings.Repeat("=", 15) + fmt.Sprintf("%019d", boundaryToken()) + "=="
	b := boundary
	for counter := 0; boundaryInText(text, b); counter++ {
		b = fmt.Sprintf("%s.%d", boundary, counter)
	}
	return b
}

// boundaryInText reports whether a line of text is "--b" or "--b--", as the
// multiline regular expression of _make_boundary finds it: a line ends at
// "\n" or at the end of text, and a "\r" before its end is ignored.
func boundaryInText(text, b string) bool {
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSuffix(line, "\r")
		if line == "--"+b || line == "--"+b+"--" {
			return true
		}
	}
	return false
}

// generate returns the bytes of the entity, as BytesGenerator.flatten does.
func (e *entity) generate(p policy) ([]byte, error) {
	var buf bytes.Buffer
	if err := writeEntity(&buf, e, p); err != nil {
		return nil, err
	}
	return buf.Bytes(), nil
}

// writeEntity writes the headers and the body of e. The body is generated
// first, because a multipart body chooses the boundary that the
// Content-Type header carries.
func writeEntity(w *bytes.Buffer, e *entity, p policy) error {
	var body bytes.Buffer
	if err := writeBody(&body, e, p); err != nil {
		return err
	}
	for _, h := range e.headers {
		folded, err := h.fold(p)
		if err != nil {
			return err
		}
		w.WriteString(folded)
	}
	w.WriteString(p.linesep)
	w.Write(body.Bytes())
	return nil
}

// writeBody writes the payload of e, as the _handle_* methods of the
// generator do.
func writeBody(w *bytes.Buffer, e *entity, p policy) error {
	if e.raw {
		writeLines(w, e.text, p)
		return nil
	}
	switch e.maintype() {
	case "multipart":
		return writeMultipart(w, e, p)
	case "message":
		if len(e.parts) > 0 {
			return writeEntity(w, e.parts[0], p)
		}
	}
	if e.hasText {
		writeLines(w, e.text, p)
	}
	return nil
}

// writeMultipart writes the parts of a multipart entity between boundary
// lines, choosing a boundary when the entity has none.
func writeMultipart(w *bytes.Buffer, e *entity, p policy) error {
	texts := make([]string, 0, len(e.parts))
	for _, sub := range e.parts {
		var buf bytes.Buffer
		if err := writeEntity(&buf, sub, p); err != nil {
			return err
		}
		texts = append(texts, buf.String())
	}
	boundary := ""
	if h := e.get("content-type"); h != nil && h.isMedia {
		for _, prm := range h.params {
			if strings.EqualFold(prm.name, "boundary") {
				boundary = prm.value
			}
		}
	}
	if boundary == "" {
		boundary = makeBoundary(strings.Join(texts, p.linesep))
		if err := e.setParam("Content-Type", "boundary", boundary); err != nil {
			return err
		}
	}
	w.WriteString("--" + boundary + p.linesep)
	for i, text := range texts {
		if i > 0 {
			w.WriteString(p.linesep + "--" + boundary + p.linesep)
		}
		w.WriteString(text)
	}
	w.WriteString(p.linesep + "--" + boundary + "--" + p.linesep)
	return nil
}

// writeLines writes text with its line breaks changed to the policy's, as
// Generator._write_lines does.
func writeLines(w *bytes.Buffer, text string, p policy) {
	if text == "" {
		return
	}
	lines := qpLinesKeepLast(text)
	for _, line := range lines[:len(lines)-1] {
		w.WriteString(line)
		w.WriteString(p.linesep)
	}
	w.WriteString(lines[len(lines)-1])
}

// qpLinesKeepLast splits text at "\r\n", "\r" and "\n" like re.split, so the
// last element is empty when text ends with a line break.
func qpLinesKeepLast(text string) []string {
	var lines []string
	for {
		i := strings.IndexAny(text, "\r\n")
		if i < 0 {
			return append(lines, text)
		}
		lines = append(lines, text[:i])
		if text[i] == '\r' && i+1 < len(text) && text[i+1] == '\n' {
			i++
		}
		text = text[i+1:]
	}
}
